export function decodePreviewSource(id: string): string {
  const parts = (PREVIEW_PARTS as Record<string, (string | number)[]>)[id];
  if (!parts) return "";
  return parts.map(x => typeof x === "number" ? (PREVIEW_DICT as string[])[x] : _pd(x)).join("");
}
